const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const uid = () => crypto.randomUUID();
const slug = value => value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const date = value => value ? new Intl.DateTimeFormat('it-IT',{day:'numeric',month:'short',year:'numeric'}).format(new Date(value)) : 'Non ancora salvato';
const stamp = value => value ? new Intl.DateTimeFormat('it-IT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(value)) : '';
const bytes = n => n >= 1048576 ? `${(n / 1048576).toFixed(1)} MB` : `${Math.round(n / 1024)} KB`;
const paths = {comment:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 19 0Z"/><path d="M7 10h10M7 14h6"/>',overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',file:'<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><path d="M14 3v6h6M8 13h8M8 17h6"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="m21 16-5-5L5 21"/>',book:'<path d="M12 6C8 3 4 4 3 4v15c4-1 7 0 9 2 2-2 5-3 9-2V4c-4-1-7 0-9 2Zm0 0v15"/>',tag:'<path d="m3 12 9 9 9-9V3h-9z"/><circle cx="16.5" cy="7.5" r="1.2"/>',chart:'<path d="M3 3v18h18M6 15l5-5 4 3 6-8"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-2-4"/>',settings:'<path d="m10 3-1 3-3 1-3 3 2 3-1 3 3 3 3-1 3 3 3-2 3-1 2-3-1-3-3-2-1-3z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',harddrive:'<rect x="3" y="7" width="18" height="13" rx="3"/><path d="m3 10 3-6h12l3 6M6 16h.01M10 16h.01"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-4-4L5 15z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M3 16v5h18v-5"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',up:'<path d="m6 14 6-6 6 6"/>',down:'<path d="m6 10 6 6 6-6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',cloud:'<path d="M6 19a5 5 0 0 1-1-10 7 7 0 0 1 13-1 5.5 5.5 0 0 1 0 11z"/>',folder:'<path d="M3 6V4h7l2 3h9v13H3z"/>'};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.file}</svg>`;
function icons(){ $$('[data-icon]').forEach(el => {el.outerHTML = icon(el.dataset.icon);}); }
const labels = {overview:'Panoramica',contents:'Contenuti',editor:'Editor',media:'Media e gallery',fanzine:'Digital fanzine',taxonomy:'Categorie e tag',analytics:'Analytics',team:'Persone e accessi',settings:'Impostazioni',comments:'Conversazioni'};
const types = {post:'Articolo',page:'Pagina',fanzine:'Fanzine'};
const statuses = {draft:'Bozza',review:'In revisione',scheduled:'Programmato',published:'Pubblicato',archived:'Archiviato',trash:'Cestino'};
const roles = {admin:'Amministratrice',editor:'Editor',author:'Autrice',viewer:'Lettura'};
const storageKey = 'lavanda-studio-v1';
let state = {entries:[],media:[],taxonomies:[],profiles:[],revisions:[],comments:[],redirects:[],settings:{site_title:'Lavanda',tagline:'The riot witch',site_description:'Rivista antropologica e filosofica di Martina.',social_links:{},navigation:[],seo:{}},activity:[]};
let mode = 'local', config = {}, account = null, currentRoute = 'overview', editorId = null, dirty = false, autoTimer, toastTimer, mediaUrls = new Map(), mediaPicker = null, settingTab = 'general';
const filters = {search:'',status:'all',type:'all',mediaSearch:'',mediaFolder:'all',mediaType:'all',days:30};
const canEditEntry = entry => mode==='local'||can('write')&&(account?.profile?.role!=='author'||entry?.author_id===account?.user?.id&&['draft','review','trash'].includes(entry.status));
const can = permission => mode === 'local' || (permission === 'manage' ? account?.profile?.role === 'admin' : permission === 'publish' ? ['admin','editor'].includes(account?.profile?.role) : account?.profile?.role !== 'viewer');
const safeUrl = url => {try{const u = new URL(url,location.origin);return ['http:','https:','blob:'].includes(u.protocol) ? u.href : '';}catch{return '';}};
function toast(message){ $('#toast').textContent = message; $('#toast').hidden = false; clearTimeout(toastTimer); toastTimer = setTimeout(()=>$('#toast').hidden = true,4200); }
function errorText(error){return error?.message || 'Operazione non riuscita. Riprova.';}
function activity(message){state.activity.unshift({id:uid(),message,date:new Date().toISOString()});state.activity=state.activity.slice(0,40);}
function persist(){if(mode!=='local')return true;try{localStorage.setItem(storageKey,JSON.stringify(state));$('#save-status').textContent=`Salvato su questo dispositivo · ${stamp(new Date())}`;return true;}catch{throw new Error('Salvataggio locale non riuscito: spazio del browser esaurito o non disponibile. Esporta il lavoro prima di chiudere.');}}
async function request(url, options={}){const res=await fetch(url,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json','X-CMS-Request':'1',...(options.headers||{})}});let body;try{body=await res.json();}catch{throw new Error('Il CMS non ha risposto in un formato valido.');}if(!res.ok){if(res.status===401&&mode==='remote'){$('#save-status').textContent='Sessione scaduta. Accedi per salvare.';}const err=new Error(body.error?.message || body.error || (res.status===409?'Il contenuto è stato modificato da un’altra persona. Ricarica prima di salvare.':`Operazione non riuscita (${res.status}).`));err.status=res.status;throw err;}return body;}
async function resource(name){let all=[],offset=0;for(let page=0;page<100;page++){const response=await request(`/api/cms?resource=${encodeURIComponent(name)}&limit=100&offset=${offset}`);const rows=Array.isArray(response.data)?response.data:response.data?[response.data]:[];all.push(...rows);if(rows.length<100||all.length>=response.count)break;offset+=100;}return all;}
const writableFields={entries:['type','title','slug','excerpt','body','metadata','editorial_notes','status','category_id','cover_media_id','tags','seo','published_at','fanzine_pages','version'],media:['title','alt','caption','credit','folder','published','version'],taxonomies:['name','slug','kind','description','version'],profiles:['display_name','role','active','version'],comments:['entry_id','author_name','body','status','version'],redirects:['source','target','code','version'],settings:['site_title','tagline','site_description','seo','social_links','navigation','version']};
function serializeRow(resource,row){const payload=Object.fromEntries(Object.entries(row).filter(([key,value])=>(writableFields[resource]||[]).includes(key)&&value!==undefined));if(resource==='entries'){const meta=payload.metadata||{};payload.metadata=Object.fromEntries(Object.entries(meta).filter(([key])=>['issue_number','article_ids','subtitle','cover_url','image_alt','category_name','source_status'].includes(key)));if(meta.imageAlt&&!payload.metadata.image_alt)payload.metadata.image_alt=meta.imageAlt;payload.excerpt=String(payload.excerpt||'').slice(0,1000);}return payload;}
async function saveRow(resourceName,row){if(mode==='local'){const list=state[resourceName];const old=list.find(x=>x.id===row.id);if(old){Object.assign(old,row,{version:(old.version||1)+1,updated_at:new Date().toISOString()});return old;}row={...row,id:row.id||uid(),version:1,created_at:new Date().toISOString(),updated_at:new Date().toISOString()};list.unshift(row);return row;}const existing=state[resourceName]?.find(x=>x.id===row.id);const url=`/api/cms?resource=${resourceName}${existing?`&id=${encodeURIComponent(row.id)}`:''}`;const payload=serializeRow(resourceName,row);if(!existing)delete payload.version;const saved=(await request(url,{method:existing?'PATCH':'POST',body:JSON.stringify(payload)})).data;if(existing)Object.assign(existing,saved);else state[resourceName].unshift(saved);return saved;}
async function removeRow(resourceName,id){const row=state[resourceName].find(x=>x.id===id);if(!row)return;if(mode==='remote')await request(resourceName==='media'?`/api/media?id=${encodeURIComponent(id)}`:`/api/cms?resource=${resourceName}&id=${encodeURIComponent(id)}`,{method:'DELETE',body:JSON.stringify({version:row.version})});state[resourceName]=state[resourceName].filter(x=>x.id!==id);persist();}
function normalEntry(a){const text=Array.isArray(a.body)?a.body.map(section=>`${section.heading?`## ${section.heading}\n\n`:''}${section.text||''}`).join('\n\n'):a.body||'';return {...a,id:a.id||uid(),type:a.type||'post',title:a.title||'Senza titolo',slug:a.slug||slug(a.title||''),excerpt:a.excerpt||a.subtitle||'',body:text,status:statuses[a.status]?a.status:'draft',tags:a.tags||[],seo:a.seo||{},metadata:{...(a.metadata||{}),cover_url:a.image||a.metadata?.cover_url||'',image_alt:a.imageAlt||a.metadata?.image_alt||a.metadata?.imageAlt||'',subtitle:a.subtitle||a.metadata?.subtitle||''},version:a.version||1,updated_at:a.updated_at||new Date().toISOString()};}
async function seed(){try{const res=await fetch('/admin/seed.json');if(!res.ok)return;const data=await res.json();state.entries=[...(data.entries||data.articles||[]),...(data.issues||[])].map(normalEntry);state.media=(data.media||[]).map(m=>({...m,id:m.id||uid(),public_url:m.public_url||m.url,version:m.version||1}));if(!state.media.length)state.media=state.entries.filter(x=>x.metadata?.cover_url).map(e=>({id:uid(),title:e.title,alt:e.metadata.image_alt,caption:'',credit:'Studio visivo Lavanda',mime_type:'image/webp',public_url:e.metadata.cover_url,folder:'Studio fotografico',size_bytes:0,version:1}));if(data.taxonomies)state.taxonomies=data.taxonomies.map(t=>({...t,id:t.id||uid(),version:1}));else state.taxonomies=[...new Set((data.articles||data.entries||[]).map(e=>e.category||e.metadata?.category_name).filter(Boolean))].map(name=>({id:uid(),name,slug:slug(name),kind:'category',description:'',version:1}));state.entries.forEach(e=>{const original=(data.articles||data.entries||[]).find(x=>x.slug===e.slug);e.category_id=e.category_id||state.taxonomies.find(t=>t.name===(original?.category||original?.metadata?.category_name))?.id;const media=state.media.find(m=>m.public_url===e.metadata.cover_url);e.cover_media_id=e.cover_media_id||media?.id;});const f=data.fanzine||data.issue;if(f&&!state.entries.some(e=>e.type==='fanzine'))state.entries.push(normalEntry({type:'fanzine',title:f.title,slug:'numero-'+(f.number||'00'),excerpt:f.description,status:'draft',body:f.description,metadata:{issue_number:f.number||'00',article_ids:(f.articles||[]).map(s=>state.entries.find(e=>e.slug===s)?.id).filter(Boolean),cover_url:f.coverImage,subtitle:f.subtitle}}));if(data.settings)state.settings={...state.settings,...data.settings};activity('Redazione preparata con i materiali del progetto.');persist();}catch(error){console.warn('Seed non disponibile',error.message);}}
function db(){return new Promise((resolve,reject)=>{const req=indexedDB.open('lavanda-studio-media',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function blobStore(action,key,value){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('files',action==='get'?'readonly':'readwrite');const store=tx.objectStore('files');const req=action==='get'?store.get(key):action==='delete'?store.delete(key):store.put(value,key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);tx.oncomplete=()=>database.close();});}
async function hydrateMedia(){for(const m of state.media){if(m.local_file){try{const blob=await blobStore('get',m.id);if(blob){if(mediaUrls.has(m.id))URL.revokeObjectURL(mediaUrls.get(m.id));mediaUrls.set(m.id,URL.createObjectURL(blob));}}catch{}}}}
function mediaUrl(m){return safeUrl(mediaUrls.get(m?.id)||m?.public_url||'');}
function cover(entry){const m=state.media.find(m=>m.id===entry?.cover_media_id);return mediaUrl(m)||safeUrl(entry?.metadata?.cover_url||'');}
function statusPill(status){return `<span class="pill ${esc(status)}">${esc(statuses[status]||status)}</span>`;}
function pageHeading(title,description,actions=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
function empty(title,message,action='',symbol='file'){return `<div class="quiet-empty"><span class="empty-icon">${icon(symbol)}</span><h3>${esc(title)}</h3><p>${esc(message)}</p>${action}</div>`;}
function entryRows(entries){return entries.map(e=>`<div class="entry-row">${cover(e)?`<img class="entry-thumb" src="${esc(cover(e))}" alt="">`:`<span class="entry-thumb" style="display:grid;place-items:center;color:var(--muted)">${icon('file')}</span>`}<div class="entry-row-main"><button data-action="edit-entry" data-id="${esc(e.id)}">${esc(e.title)}</button><small>${esc(types[e.type])} · ${date(e.updated_at)}</small></div>${statusPill(e.status)}<button class="icon-button" data-action="edit-entry" data-id="${esc(e.id)}" aria-label="Modifica ${esc(e.title)}">${icon('arrow')}</button></div>`).join('');}
function renderOverview(){const entries=state.entries.filter(e=>e.status!=='trash');const articles=entries.filter(e=>e.type==='post');const drafts=entries.filter(e=>['draft','review'].includes(e.status));const fanzines=entries.filter(e=>e.type==='fanzine');const latest=[...entries].sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at)).slice(0,5);$('#main').innerHTML=pageHeading('Ogni ricerca prende forma.','Il tuo spazio per scrivere, raccogliere e comporre Lavanda.',`<button data-action="view-site">${icon('external')}Apri il sito</button><button class="primary" data-action="new-entry">${icon('plus')}Nuovo contenuto</button>`)+`<div class="stat-grid"><div class="stat"><span>${icon('file')}Articoli</span><strong>${articles.length}</strong><small>${articles.filter(e=>e.status==='published').length} pubblicati${mode==='local'?' nello spazio locale':''}</small></div><div class="stat"><span>${icon('edit')}In lavorazione</span><strong>${drafts.length}</strong><small>Bozze e revisioni</small></div><div class="stat"><span>${icon('image')}Media</span><strong>${state.media.length}</strong><small>Immagini e documenti</small></div><div class="stat"><span>${icon('book')}Digital fanzine</span><strong>${fanzines.length}</strong><small>Numeri in redazione</small></div></div><div class="two-columns"><div><div class="welcome"><div><h2>Uno spazio per<br>le tue corrispondenze.</h2><p>Dal primo appunto a un nuovo numero. Tutto il percorso editoriale, nello stesso posto.</p><button data-action="new-entry">${icon('plus')}Inizia a scrivere</button></div><img src="/brand/emblem.svg" alt=""></div><section class="panel no-pad"><div class="section-pad section-heading"><div><h2>Sulla scrivania</h2><p>I contenuti aggiornati di recente.</p></div><a class="text-button" href="#contents">Tutti i contenuti</a></div>${latest.length?entryRows(latest):empty('La prima pagina è tua.','Aggiungi un articolo o una pagina per iniziare.',`<button data-action="new-entry">Nuovo contenuto</button>`)}</section></div><div><section class="panel"><div class="section-heading"><div><h2>La redazione, adesso</h2><p>Attività di questo spazio.</p></div>${icon('clock')}</div><div class="activity-list">${state.activity.length?state.activity.slice(0,5).map(a=>`<div class="activity"><span class="activity-dot"></span><div><p>${esc(a.message)}</p><small>${stamp(a.date)}</small></div></div>`).join(''):`<p class="muted small">Le prossime modifiche compariranno qui.</p>`}</div></section><section class="panel" style="margin-top:22px"><div class="section-heading"><h2>Letture e visite</h2>${icon('chart')}</div>${empty('Le prime letture arriveranno qui.',mode==='local'?'Le analytics reali si attivano dopo il collegamento al CMS e la pubblicazione del sito.':'Apri le analytics per consultare i dati aggregati del sito.',`<a class="text-button" href="#analytics">Apri analytics</a>`,'chart')}</section></div></div>`;}
function contentTable(){const entries=state.entries.filter(e=>(filters.status==='all'?e.status!=='trash':e.status===filters.status)&&(filters.type==='all'||e.type===filters.type)&&`${e.title} ${e.excerpt} ${e.slug}`.toLowerCase().includes(filters.search.toLowerCase()));return entries.length?`<div class="panel no-pad"><div class="table-wrap"><table><thead><tr><th>Contenuto</th><th>Stato</th><th class="table-hidden">Categoria</th><th class="table-hidden">Aggiornato</th><th><span class="sr-only">Azioni</span></th></tr></thead><tbody>${entries.map(e=>`<tr><td><div class="title-cell">${cover(e)?`<img src="${esc(cover(e))}" alt="">`:icon('file')}<div><button data-action="edit-entry" data-id="${esc(e.id)}">${esc(e.title)}</button><small>${esc(types[e.type])} /${esc(e.slug)}</small></div></div></td><td>${statusPill(e.status)}</td><td class="table-hidden muted small">${esc(state.taxonomies.find(c=>c.id===e.category_id)?.name||'Senza categoria')}</td><td class="table-hidden muted small">${date(e.updated_at)}</td><td><div class="table-actions"><button data-action="edit-entry" data-id="${esc(e.id)}" aria-label="Modifica ${esc(e.title)}">${icon('edit')}</button><button data-action="duplicate-entry" data-id="${esc(e.id)}" aria-label="Duplica ${esc(e.title)}">${icon('copy')}</button><button data-action="trash-entry" data-id="${esc(e.id)}" aria-label="${e.status==='trash'?(mode==='remote'?'Ripristina come bozza':'Elimina definitivamente'):'Sposta nel cestino'} ${esc(e.title)}">${icon(e.status==='trash'&&mode==='remote'?'up':'trash')}</button></div></td></tr>`).join('')}</tbody></table></div></div><p class="muted small" style="padding:10px 3px">${entries.length} contenuti${mode==='local'?' · Salvati solo su questo dispositivo':''}</p>`:empty('Nessun contenuto in questa vista.','Prova a cambiare i filtri oppure inizia una nuova pagina.',`<button data-action="new-entry">${icon('plus')}Nuovo contenuto</button>`);}
function renderContents(){const counts=Object.keys(statuses).map(s=>[s,state.entries.filter(e=>e.status===s).length]);$('#main').innerHTML=pageHeading('Contenuti','Articoli, pagine e bozze. Ogni parola, al suo posto.',`<button data-action="export">${icon('download')}Esporta</button><button class="primary" data-action="new-entry">${icon('plus')}Nuovo contenuto</button>`)+`<div class="tabs" role="tablist" aria-label="Stato contenuti"><button role="tab" data-status="all" aria-selected="${filters.status==='all'}">Tutti ${state.entries.filter(e=>e.status!=='trash').length}</button>${counts.map(([s,c])=>`<button role="tab" data-status="${s}" aria-selected="${filters.status===s}">${statuses[s]} ${c}</button>`).join('')}</div><div class="toolbar"><label class="search">${icon('search')}<input id="content-search" placeholder="Cerca titolo, testo o indirizzo…" aria-label="Cerca contenuti" value="${esc(filters.search)}"></label><select id="type-filter" aria-label="Tipo di contenuto"><option value="all">Tutti i tipi</option>${Object.entries(types).map(([v,l])=>`<option value="${v}" ${filters.type===v?'selected':''}>${l}</option>`).join('')}</select></div><div id="contents-results">${contentTable()}</div>`;}
function words(text){return text.trim().split(/\s+/).filter(Boolean).length;}
function renderEditor(){const entry=state.entries.find(e=>e.id===editorId);if(!entry){location.hash='contents';return;}const categoryOptions=state.taxonomies.filter(t=>t.kind==='category');$('#main').innerHTML=pageHeading(entry.title||'Nuovo contenuto',mode==='local'?'Bozza locale. Le modifiche non vengono pubblicate sul sito.':'Scrivi, rivedi e pubblica dalla redazione.',`<button data-action="revisions" data-id="${esc(entry.id)}">${icon('clock')}Revisioni</button><button data-action="preview" data-id="${esc(entry.id)}">${icon('eye')}Anteprima</button><button class="primary" data-action="save-editor">${icon('check')}Salva ${mode==='local'?'bozza':''}</button>`)+`<form id="editor-form" data-id="${esc(entry.id)}"><div class="editor-layout"><div class="editor-main"><section class="panel"><label class="sr-only" for="entry-title">Titolo</label><textarea id="entry-title" name="title" class="editor-title" rows="2" maxlength="240" required placeholder="Il titolo della tua ricerca">${esc(entry.title==='Senza titolo'?'':entry.title)}</textarea><label class="sr-only" for="entry-excerpt">Sommario</label><textarea id="entry-excerpt" name="excerpt" class="editor-subtitle" rows="2" maxlength="1000" placeholder="Un’introduzione, una domanda, il punto da cui partire…">${esc(entry.excerpt)}</textarea><div class="editor-tools" aria-label="Inserisci un blocco"><button type="button" data-block="heading">Titolo sezione</button><button type="button" data-block="paragraph">Paragrafo</button><button type="button" data-block="quote">Citazione</button><button type="button" data-block="list">Elenco</button><button type="button" data-block="image">Immagine</button><button type="button" data-block="separator">Separatore</button></div><label class="sr-only" for="entry-body">Testo del contenuto</label><textarea id="entry-body" name="body" class="editor-body" placeholder="La pagina è aperta. Inizia da qui…">${esc(entry.body)}</textarea><div class="editor-count"><span id="word-count">${words(entry.body)} parole</span><span id="reading-time">${Math.max(1,Math.ceil(words(entry.body)/200))} minuti di lettura</span><span id="editor-save-label">Salvato ${stamp(entry.updated_at)}</span></div></section><section class="panel"><div class="section-heading"><div><h2>Ricerca e fonti</h2><p>Riferimenti e note per la redazione.</p></div></div><label>Note editoriali<textarea name="source_note" rows="3" placeholder="Bibliografia, appunti, attribuzioni…">${esc(entry.editorial_notes||entry.metadata?.source_note||entry.sourceNote||'')}</textarea></label></section></div><aside class="editor-aside"><section class="panel"><h2>Il contenuto</h2><div class="field-stack"><label>Tipo<select name="type">${Object.entries(types).map(([v,l])=>`<option value="${v}" ${entry.type===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Stato<select name="status">${Object.entries(statuses).filter(([v])=>v!=='trash'&&(mode==='remote'||v!=='published'&&v!=='scheduled')).map(([v,l])=>`<option value="${v}" ${entry.status===v?'selected':''}>${mode==='local'&&v==='review'?'Da rivedere':l}</option>`).join('')}</select></label>${mode==='remote'?`<label>Data di pubblicazione<input type="datetime-local" name="published_at" value="${entry.published_at?esc(entry.published_at.slice(0,16)):''}"></label>`:''}<label>Indirizzo<input name="slug" value="${esc(entry.slug)}" required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" placeholder="titolo-del-contenuto"><span class="field-note">/lettura/?slug=<span id="slug-preview">${esc(entry.slug)}</span></span></label><label>Categoria<select name="category_id"><option value="">Senza categoria</option>${categoryOptions.map(c=>`<option value="${esc(c.id)}" ${entry.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Tag<input name="tags" value="${esc((entry.tags||[]).join(', '))}" placeholder="cicli, archetipi, botanica"><span class="field-note">Separa i tag con una virgola.</span></label></div></section><section class="panel"><h2>Immagine di copertina</h2>${cover(entry)?`<img class="editor-cover" src="${esc(cover(entry))}" alt="${esc(entry.metadata?.image_alt||'')}">`:`<div class="cover-placeholder">${icon('image')}</div>`}<button type="button" class="wide" data-action="pick-cover" data-id="${esc(entry.id)}">${icon('image')}${cover(entry)?'Cambia immagine':'Scegli dalla libreria'}</button>${cover(entry)?`<button type="button" class="text-button" data-action="remove-cover" data-id="${esc(entry.id)}">Rimuovi copertina</button>`:''}</section><section class="panel"><h2>Motori di ricerca</h2><div class="field-stack"><label>Titolo SEO<input name="seo_title" maxlength="70" value="${esc(entry.seo?.title||'')}" placeholder="${esc(entry.title)}"><span class="field-note">Consigliato: fino a 60 caratteri.</span></label><label>Descrizione<textarea name="seo_description" rows="3" maxlength="320" placeholder="Come apparirà questo contenuto nei risultati di ricerca…">${esc(entry.seo?.description||'')}</textarea></label><label>URL canonico<input name="canonical" type="url" value="${esc(entry.seo?.canonical||'')}" placeholder="https://…"></label><label class="check-field"><input type="checkbox" name="noindex" ${entry.seo?.noindex?'checked':''}>Escludi dai motori di ricerca</label></div></section></aside></div></form>`;if(!canEditEntry(entry)){$$('input,select,textarea,#editor-form button,[data-action=save-editor]',$('#main')).forEach(x=>x.disabled=true);}}
function collectEditor(){const form=$('#editor-form');if(!form)return null;const old=state.entries.find(e=>e.id===form.dataset.id);const fd=new FormData(form);const title=fd.get('title').trim();return {...old,title:title||'Senza titolo',excerpt:fd.get('excerpt'),body:fd.get('body'),type:fd.get('type'),status:fd.get('status')||'draft',slug:fd.get('slug')||slug(title),category_id:fd.get('category_id')||null,tags:fd.get('tags').split(',').map(t=>t.trim()).filter(Boolean),seo:{title:fd.get('seo_title'),description:fd.get('seo_description'),canonical:fd.get('canonical'),noindex:fd.has('noindex')},metadata:{...old.metadata},editorial_notes:fd.get('source_note'),published_at:fd.get('published_at')?new Date(fd.get('published_at')).toISOString():old.published_at||null};}
async function saveEditor(manual=true){if(!$('#editor-form')||!dirty&&!manual)return true;const form=$('#editor-form');if(manual&&!form.reportValidity())return false;const entry=collectEditor();if(!entry)return;const old=state.entries.find(e=>e.id===entry.id);if(!canEditEntry(old)){toast('Il tuo ruolo non consente di modificare questo contenuto.');return false;}if(mode==='remote'&&!can('publish')&&['published','scheduled'].includes(entry.status))return toast('Il tuo ruolo non consente la pubblicazione.');try{if(mode==='local'){state.revisions.unshift({id:uid(),entry_id:entry.id,snapshot:JSON.parse(JSON.stringify(old)),created_at:new Date().toISOString()});state.revisions=state.revisions.slice(0,120);}const saved=await saveRow('entries',entry);activity(`${mode==='local'?'Bozza salvata':'Contenuto salvato'}: ${saved.title}.`);persist();dirty=false;$('#editor-save-label').textContent=`Salvato ${stamp(saved.updated_at)}`;$('#save-status').textContent=`${mode==='local'?'Salvato su questo dispositivo':'Sincronizzato'} · ${stamp(saved.updated_at)}`;if(manual)toast(mode==='local'?'Bozza salvata su questo dispositivo.':'Contenuto salvato nel CMS.');return true;}catch(error){$('#save-status').textContent='Salvataggio non riuscito';toast(errorText(error));return false;}}
function renderMedia(){const folders=[...new Set(state.media.map(m=>m.folder||'Senza cartella'))];$('#main').innerHTML=pageHeading('La tua materia visiva.','Immagini, illustrazioni e documenti. Uno spazio per raccogliere e ritrovare.',`<button class="primary" data-action="upload">${icon('upload')}Carica media</button>`)+`<div class="drop-zone" id="drop-zone">${icon('upload')}<div><strong>Trascina qui i tuoi file</strong><span class="drop-secondary"> · Immagini e PDF, fino a 3 MB per file.</span></div><button data-action="upload">Scegli file</button></div><div class="toolbar"><label class="search">${icon('search')}<input id="media-search" placeholder="Cerca per nome, descrizione o credito…" aria-label="Cerca media" value="${esc(filters.mediaSearch)}"></label><select id="media-folder" aria-label="Cartella media"><option value="all">Tutte le cartelle</option>${folders.map(f=>`<option value="${esc(f)}" ${f===filters.mediaFolder?'selected':''}>${esc(f)}</option>`).join('')}</select><select id="media-type" aria-label="Tipo media"><option value="all">Tutti i media</option><option value="image" ${filters.mediaType==='image'?'selected':''}>Immagini</option><option value="pdf" ${filters.mediaType==='pdf'?'selected':''}>PDF</option></select></div><div id="media-results">${mediaGrid()}</div>`;}
function mediaGrid(picker=false){const files=state.media.filter(m=>`${m.title} ${m.alt} ${m.caption} ${m.credit}`.toLowerCase().includes(filters.mediaSearch.toLowerCase())&&(filters.mediaFolder==='all'||(m.folder||'Senza cartella')===filters.mediaFolder)&&(filters.mediaType==='all'||filters.mediaType==='image'&&m.mime_type?.startsWith('image/')||filters.mediaType==='pdf'&&m.mime_type==='application/pdf'));return files.length?`<div class="media-grid">${files.map(m=>`<article class="media-card"><button class="media-image" data-action="${picker?'select-media':'media-detail'}" data-id="${esc(m.id)}" aria-label="${picker?'Seleziona':'Modifica'} ${esc(m.title)}">${m.mime_type==='application/pdf'?`<span class="file-placeholder">PDF</span>`:`<img loading="lazy" src="${esc(mediaUrl(m))}" alt="${esc(m.alt)}">`}</button><div class="media-caption"><strong>${esc(m.title)}</strong><small>${esc(m.folder||'Senza cartella')} ${m.size_bytes?`· ${bytes(m.size_bytes)}`:''}</small></div></article>`).join('')}</div>`:empty('La libreria aspetta le tue immagini.','Carica una fotografia, un’illustrazione o un PDF per iniziare.',`<button data-action="upload">${icon('upload')}Carica media</button>`,'image');}
function showModal(title,body,wide=false,subtitle=''){const modal=$('#modal');modal.classList.toggle('wide-dialog',wide);$('#modal-content').innerHTML=`<div class="dialog-heading"><div><h2 id="modal-title">${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Chiudi">${icon('close')}</button></div>${body}`;if(!modal.open)modal.showModal();}
function closeModal(){const modal=$('#modal');modal.close();mediaPicker=null;}
function showMedia(id){const m=state.media.find(x=>x.id===id);if(!m)return;showModal('Dettagli del media',`<div class="media-detail"><div>${m.mime_type==='application/pdf'?`<div class="cover-placeholder">${icon('file')}Documento PDF</div>`:`<img src="${esc(mediaUrl(m))}" alt="${esc(m.alt)}">`}<div class="meta-list" style="margin-top:20px"><div>Formato<strong>${esc(m.mime_type||'Immagine')}</strong></div><div>Dimensione<strong>${m.size_bytes?bytes(m.size_bytes):'Asset del progetto'}</strong></div><div>Archiviazione<strong>${m.local_file?'Questo dispositivo':mode==='remote'?'CMS collegato':'Materiali del progetto'}</strong></div><div>Indirizzo<strong>${esc(m.local_file?'File locale':m.public_url)}</strong></div></div></div><form id="media-form" data-id="${esc(m.id)}" class="field-stack"><label>Nome<input name="title" value="${esc(m.title)}" required></label><label>Testo alternativo<textarea name="alt" rows="2" placeholder="Descrivi ciò che rende significativa l’immagine…">${esc(m.alt)}</textarea><span class="field-note">Aiuta chi usa un lettore di schermo. Lascia vuoto per immagini decorative.</span></label><label>Didascalia<textarea name="caption" rows="2">${esc(m.caption)}</textarea></label><label>Crediti e diritti<input name="credit" value="${esc(m.credit)}"></label><label>Cartella<input name="folder" value="${esc(m.folder)}" placeholder="Studio fotografico"></label>${mode==='remote'?`<label class="check-field"><input type="checkbox" name="published" ${m.published?'checked':''} ${!can('publish')?'disabled':''}>Rendi disponibile sul sito pubblico</label><p class="field-note">Le copertine pubblicate devono essere disponibili anche ai lettori.</p>`:''}<div class="dialog-actions"><button type="button" class="danger" data-action="delete-media" data-id="${esc(m.id)}">Elimina</button><button class="primary" type="submit">Salva dettagli</button></div></form></div>`,true);}
async function uploadFiles(files){if(!can('write'))return toast('Il tuo ruolo non consente il caricamento.');let count=0;for(const file of files){if(!['image/jpeg','image/png','image/webp','image/gif','image/avif','application/pdf'].includes(file.type)){toast(`${file.name}: formato non supportato.`);continue;}if(file.size>3*1024*1024){toast(`${file.name}: supera il limite di 3 MB.`);continue;}try{let row;if(mode==='local'){const id=uid();await blobStore('put',id,file);row={id,title:file.name.replace(/\.[^.]+$/,''),filename:file.name,mime_type:file.type,size_bytes:file.size,alt:'',caption:'',credit:'',folder:'Caricamenti',local_file:true,version:1,created_at:new Date().toISOString()};state.media.unshift(row);mediaUrls.set(id,URL.createObjectURL(file));}else{const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});row=(await request('/api/media',{method:'POST',body:JSON.stringify({filename:file.name,mime_type:file.type,content_base64:base64,title:file.name.replace(/\.[^.]+$/,''),alt:'',folder:'Caricamenti'})})).data;state.media.unshift(row);}count++;activity(`Media aggiunto: ${row.title}.`);}catch(error){toast(errorText(error));}}try{persist();}catch(error){toast(errorText(error));return;}if(currentRoute==='media')renderMedia();if(mediaPicker)openMediaPicker(mediaPicker);if(count)toast(`${count} ${count===1?'media caricato':'media caricati'}${mode==='local'?' su questo dispositivo':''}.`);$('#file-input').value='';}
function openMediaPicker(entryId){mediaPicker=entryId;showModal('Scegli un’immagine',`<p class="muted small" style="margin-bottom:20px">La copertina accompagnerà il contenuto nelle raccolte e nei risultati di ricerca.</p>${mediaGrid(true)}<div class="dialog-actions"><button data-action="upload">${icon('upload')}Carica un’immagine</button></div>`,true);mediaPicker=entryId;}
function renderFanzine(){const issues=state.entries.filter(e=>e.type==='fanzine'&&e.status!=='trash');$('#main').innerHTML=pageHeading('Digital fanzine','Componi un numero, scegli le voci, costruisci il ritmo della lettura.',`<button class="primary" data-action="new-issue">${icon('plus')}Nuovo numero</button>`)+(issues.length?issues.map(e=>`<section class="panel"><div class="issue-card"><div class="issue-cover">${cover(e)?`<img src="${esc(cover(e))}" alt="">`:''}<span>lavanda</span><strong>${esc(e.title)}</strong><small>Numero ${esc(e.metadata?.issue_number||'00')}</small></div><div class="issue-info">${statusPill(e.status)}<h2>${esc(e.title)}</h2><p>${esc(e.excerpt)}</p><p class="small">${(e.metadata?.article_ids||[]).length} contributi · Numero ${esc(e.metadata?.issue_number||'00')}</p><button data-action="edit-issue" data-id="${esc(e.id)}">${icon('book')}Componi il numero</button> <button class="text-button" data-action="edit-entry" data-id="${esc(e.id)}">Testo e impostazioni</button></div></div></section>`).join(''):empty('Il prossimo numero inizia qui.','Scegli un tema e raccogli gli articoli in una sequenza di lettura.',`<button data-action="new-issue">${icon('plus')}Nuovo numero</button>`,'book'));}
function showIssue(id){const e=state.entries.find(x=>x.id===id);const articleIds=e.metadata?.article_ids||[];const candidates=state.entries.filter(x=>x.type==='post'&&x.status!=='trash'&&!articleIds.includes(x.id));showModal(`Componi: ${e.title}`,`<form id="issue-form" data-id="${esc(e.id)}"><div class="field-grid"><label>Titolo del numero<input name="title" value="${esc(e.title)}" required></label><label>Numero<input name="issue_number" value="${esc(e.metadata?.issue_number||'00')}" required maxlength="12"></label></div><label style="margin-top:18px">Sottotitolo<input name="subtitle" value="${esc(e.metadata?.subtitle||'')}"></label><div class="section-heading" style="margin-top:25px"><h2>Il percorso di lettura</h2><span class="muted small">${articleIds.length} contributi</span></div><ol class="reorder-list">${articleIds.map((id,i)=>{const a=state.entries.find(x=>x.id===id);return `<li><span>${i+1}. ${esc(a?.title||'Contenuto non disponibile')}</span><button type="button" data-action="issue-up" data-id="${esc(id)}" data-issue="${esc(e.id)}" aria-label="Sposta su ${esc(a?.title)}" ${i===0?'disabled':''}>${icon('up')}</button><button type="button" data-action="issue-down" data-id="${esc(id)}" data-issue="${esc(e.id)}" aria-label="Sposta giù ${esc(a?.title)}" ${i===articleIds.length-1?'disabled':''}>${icon('down')}</button><button type="button" data-action="issue-remove" data-id="${esc(id)}" data-issue="${esc(e.id)}" aria-label="Rimuovi ${esc(a?.title)} dal numero">${icon('close')}</button></li>`;}).join('')}</ol>${candidates.length?`<div class="inline-add"><select id="issue-add-select" aria-label="Articolo da aggiungere">${candidates.map(a=>`<option value="${esc(a.id)}">${esc(a.title)}</option>`).join('')}</select><button type="button" data-action="issue-add" data-issue="${esc(e.id)}" aria-label="Aggiungi al numero">${icon('plus')}</button></div>`:`<p class="muted small">Tutti gli articoli disponibili sono già in questo numero.</p>`}${issuePageFields(e)}<div class="notice" style="margin-top:20px">${mode==='local'?'Il numero è una composizione locale. La pubblicazione e l’uscita pubblica richiedono il collegamento al CMS.':'Per rendere pubblico il numero, apri Testo e impostazioni e cambia lo stato in Pubblicato.'}</div><div class="dialog-actions"><button type="button" data-action="close-modal">Chiudi</button><button class="primary" type="submit">Salva numero</button></div></form>`);}
function renderTaxonomy(){const section=kind=>`<section class="panel"><div class="section-heading"><div><h2>${kind==='category'?'Categorie':'Tag'}</h2><p>${kind==='category'?'Le aree di ricerca della rivista.':'I fili che attraversano gli articoli.'}</p></div>${icon('tag')}</div><ul class="taxonomy-list">${state.taxonomies.filter(t=>t.kind===kind).map(t=>`<li><div>${esc(t.name)}<small class="muted" style="display:block;font-size:9px">/${esc(t.slug)}</small></div><span class="pill">${kind==='category'?state.entries.filter(e=>e.category_id===t.id).length:state.entries.filter(e=>e.tags?.includes(t.name)).length} contenuti</span><button data-action="edit-taxonomy" data-id="${esc(t.id)}" aria-label="Modifica ${esc(t.name)}">${icon('edit')}</button><button data-action="delete-taxonomy" data-id="${esc(t.id)}" aria-label="Elimina ${esc(t.name)}">${icon('trash')}</button></li>`).join('')||`<li class="muted">${kind==='category'?'Nessuna categoria.':'Nessun tag.'}</li>`}</ul><form class="inline-add taxonomy-add" data-kind="${kind}"><label class="sr-only" for="new-${kind}">Nuova ${kind==='category'?'categoria':'etichetta'}</label><input id="new-${kind}" name="name" placeholder="${kind==='category'?'Nuova categoria':'Nuovo tag'}" required maxlength="100"><button class="primary" aria-label="Aggiungi ${kind==='category'?'categoria':'tag'}">${icon('plus')}</button></form></section>`;$('#main').innerHTML=pageHeading('Categorie e tag','Un’architettura leggibile per collegare le tue ricerche.')+`<div class="equal-columns">${section('category')}${section('tag')}</div>`;}
async function renderAnalytics(){const days=filters.days;$('#main').innerHTML=pageHeading('Le tracce di chi legge.','Analytics aggregate del sito. Nessun numero inventato.',`<select id="analytics-days" aria-label="Periodo analytics" style="border-radius:22px;font-size:11px"><option value="7" ${days===7?'selected':''}>Ultimi 7 giorni</option><option value="30" ${days===30?'selected':''}>Ultimi 30 giorni</option><option value="90" ${days===90?'selected':''}>Ultimi 90 giorni</option></select><button data-action="analytics-export">${icon('download')}Esporta CSV</button>`)+`<div id="analytics-body"><div class="loading"><span class="loader"></span>Caricamento dati…</div></div>`;let data=null;try{if(mode==='remote'&&config.analyticsConfigured)data=(await request(`/api/cms?resource=analytics&days=${days}`)).data;}catch(error){if(currentRoute==='analytics')$('#analytics-body').innerHTML=`<div class="error-message">${esc(errorText(error))}</div>`;return;}if(currentRoute!=='analytics')return;window.__lavandaAnalytics=data;const totals=data?.totals;const stats=[['page_view','Visualizzazioni','Letture di pagina'],['article_open','Articoli aperti','Aperture registrate'],['fanzine_open','Letture fanzine','Aperture del numero'],['download','Download','Documenti scaricati']];const daily=data?.daily||[];const points=Array.from({length:days},(_,i)=>{const d=new Date();d.setUTCDate(d.getUTCDate()-days+1+i);const day=d.toISOString().slice(0,10);return {day,count:daily.filter(x=>x.date?.slice(0,10)===day&&x.event==='page_view').reduce((a,x)=>a+Number(x.count),0)};});const max=Math.max(1,...points.map(p=>p.count));const hasData=points.some(p=>p.count);const chart=hasData?`<svg viewBox="0 0 900 230" preserveAspectRatio="none" role="img" aria-label="Andamento delle visualizzazioni nei ${days} giorni"><polyline points="${points.map((p,i)=>`${i*900/Math.max(1,days-1)},${220-p.count/max*200}`).join(' ')}" fill="none" stroke="#3193ec" stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg>`:`<div class="chart-empty"><strong>${data?'Le prime visite arriveranno qui.':'In attesa del collegamento.'}</strong><span>${data?'Nessuna visualizzazione registrata nel periodo selezionato.':'Collega il CMS per raccogliere dati reali dal sito.'}</span></div>`;$('#analytics-body').innerHTML=`<div class="stat-grid">${stats.map(([key,title,note])=>`<div class="stat"><span>${esc(title)}</span><strong>${totals?Number(totals[key]||0).toLocaleString('it-IT'):'—'}</strong><small>${totals?note:'Raccolta non collegata'}</small></div>`).join('')}</div><section class="panel"><div class="section-heading"><div><h2>Il ritmo delle letture</h2><p>Visualizzazioni di pagina, negli ultimi ${days} giorni.</p></div><span class="chart-key">Visualizzazioni</span></div><div class="analytics-chart">${chart}</div><div class="chart-days"><span>${date(points[0].day)}</span><span>${date(points[Math.floor(days/2)].day)}</span><span>${date(points[days-1].day)}</span></div></section><div class="equal-columns" style="margin-top:22px"><section class="panel"><div class="section-heading"><h2>Pagine più lette</h2></div>${data?.pages?.length?`<table><thead><tr><th>Pagina</th><th>Visualizzazioni</th></tr></thead><tbody>${data.pages.map(p=>`<tr><td>${esc(p.path)}</td><td>${Number(p.count).toLocaleString('it-IT')}</td></tr>`).join('')}</tbody></table>`:empty('Nessuna lettura da ordinare.','Le pagine visitate compariranno qui appena saranno disponibili i primi dati.','','chart')}</section><section class="panel"><div class="section-heading"><h2>Come leggiamo questi dati</h2>${icon('lock')}</div><p class="muted small" style="line-height:1.9">Il sistema conta eventi aggregati, senza creare profili dei lettori. Le visualizzazioni non corrispondono a persone uniche. I dati dipendono dal caricamento del sito e possono essere ridotti da blocchi del browser.</p><div class="notice" style="margin-top:20px"><strong>${data?'Raccolta attiva':'Analytics non collegate'}</strong><br>${data?'Dati reali dal CMS. Nessun identificatore personale nelle statistiche.':'Le statistiche appariranno quando database e raccolta eventi saranno configurati.'}</div></section></div>`;}
function renderTeam(){const profiles=mode==='remote'?state.profiles:[];$('#main').innerHTML=pageHeading('Persone e accessi','Una redazione chiara. Ogni persona con il suo spazio e i suoi permessi.',can('manage')&&mode==='remote'?`<button class="primary" data-action="team-add">${icon('plus')}Aggiungi persona</button>`:'')+`<section class="panel no-pad"><div class="section-pad section-heading"><div><h2>La redazione</h2><p>${mode==='local'?'Gli account reali saranno disponibili nel CMS collegato.':'Accessi registrati nel progetto.'}</p></div></div>${profiles.length?`<table><thead><tr><th>Persona</th><th>Ruolo</th><th>Stato</th><th>Azioni</th></tr></thead><tbody>${profiles.map(p=>`<tr><td>${esc(p.display_name||p.id)}${p.id===account?.user?.id?'<span class="pill" style="margin-left:8px">Tu</span>':''}</td><td>${esc(roles[p.role]||p.role)}</td><td>${p.active?'Attivo':'Sospeso'}</td><td>${can('manage')?`<button data-action="edit-profile" data-id="${esc(p.id)}" style="font-size:11px">Modifica</button>`:''}</td></tr>`).join('')}</tbody></table>`:empty('Le persone prima dei permessi.','Collega il CMS per creare accessi personali. La modalità locale non genera utenti o inviti.',`<button data-action="connect">${icon('lock')}Gestisci collegamento</button>`,'users')}</section><section class="panel"><div class="section-heading"><div><h2>Chi può fare cosa</h2><p>I permessi vengono controllati anche dal server.</p></div></div><div class="table-wrap"><table class="permissions"><thead><tr><th>Funzione</th><th>Amministratrice</th><th>Editor</th><th>Autrice</th><th>Lettura</th></tr></thead><tbody><tr><td>Leggere contenuti e analytics</td><td>Sì</td><td>Sì</td><td>Sì</td><td>Sì</td></tr><tr><td>Scrivere bozze proprie</td><td>Sì</td><td>Sì</td><td>Sì</td><td>—</td></tr><tr><td>Modificare tutti i contenuti</td><td>Sì</td><td>Sì</td><td>—</td><td>—</td></tr><tr><td>Pubblicare</td><td>Sì</td><td>Sì</td><td>—</td><td>—</td></tr><tr><td>Gestire accessi e impostazioni</td><td>Sì</td><td>—</td><td>—</td><td>—</td></tr></tbody></table></div></section>`;}
function renderSettings(){const s=state.settings;const tabs=[['general','Il progetto'],['seo','Ricerca e condivisione'],['navigation','Navigazione'],['redirects','Reindirizzamenti'],['data','Dati e backup']];let body='';if(settingTab==='general')body=`<h2>Il progetto</h2><p>Il nome, la voce e i contatti pubblici di Lavanda.</p><form id="settings-form"><div class="panel field-stack"><label>Nome del sito<input name="site_title" required value="${esc(s.site_title)}"></label><label>Sottotitolo<input name="tagline" value="${esc(s.tagline)}"></label><label>Descrizione del progetto<textarea name="site_description" rows="4">${esc(s.site_description)}</textarea></label><label>Instagram<input type="url" name="instagram" value="${esc(s.social_links?.instagram||'')}" placeholder="https://www.instagram.com/…"></label><div class="form-actions"><button class="primary" type="submit">Salva impostazioni</button><span class="muted small">${mode==='local'?'Solo su questo dispositivo':''}</span></div></div></form>`;if(settingTab==='seo')body=`<h2>Ricerca e condivisione</h2><p>Impostazioni generali. Ogni articolo può avere titolo e descrizione propri.</p><form id="seo-settings-form"><div class="panel field-stack"><label>Titolo predefinito<input name="title" maxlength="100" value="${esc(s.seo?.title||'')}" placeholder="Lavanda · The riot witch"></label><label>Descrizione predefinita<textarea name="description" rows="3" maxlength="320">${esc(s.seo?.description||'')}</textarea></label><label>Indirizzo principale<input name="canonical" type="url" value="${esc(s.seo?.canonical||'')}" placeholder="https://…"></label><label class="check-field"><input name="noindex" type="checkbox" ${s.seo?.noindex?'checked':''}>Chiedi ai motori di ricerca di non indicizzare il sito</label><div class="form-actions"><button class="primary">Salva impostazioni SEO</button></div></div></form>`;if(settingTab==='navigation')body=`<h2>Navigazione</h2><p>Gestisci etichette e collegamenti del menu del sito.</p><div class="panel"><ol class="reorder-list">${(s.navigation||[]).map((n,i)=>`<li><span>${esc(n.label)}<small style="display:block;color:var(--muted)">${esc(n.href)}</small></span><button data-action="nav-up" data-index="${i}" aria-label="Sposta su ${esc(n.label)}" ${i===0?'disabled':''}>${icon('up')}</button><button data-action="nav-remove" data-index="${i}" aria-label="Rimuovi ${esc(n.label)}">${icon('close')}</button></li>`).join('')||'<p class="muted small">Aggiungi il primo collegamento.</p>'}</ol><form id="nav-form" class="field-stack"><div class="field-grid"><label>Etichetta<input name="label" required placeholder="La rivista"></label><label>Collegamento<input name="href" required placeholder="/manifesto/"></label></div><button class="primary" style="justify-self:start">${icon('plus')}Aggiungi al menu</button></form></div>`;if(settingTab==='redirects')body=`<h2>Reindirizzamenti</h2><p>Conserva i collegamenti quando cambia l’indirizzo di una pagina.</p><div class="panel"><div class="notice">${mode==='local'?'Nello spazio locale puoi preparare i reindirizzamenti. Saranno attivi solo dopo la configurazione del CMS.':'I reindirizzamenti attivi vengono risolti dal sito pubblico.'}</div><ul class="taxonomy-list">${state.redirects.map(r=>`<li><span>${esc(r.source)}<small style="display:block;font-size:10px;color:var(--muted)">${r.code} → ${esc(r.target)}</small></span><button data-action="delete-redirect" data-id="${esc(r.id)}" aria-label="Elimina reindirizzamento ${esc(r.source)}">${icon('trash')}</button></li>`).join('')}</ul><form id="redirect-form" class="field-stack" style="margin-top:20px"><label>Vecchio percorso<input name="source" required pattern="/.*" placeholder="/vecchio-articolo/"></label><label>Nuovo percorso<input name="target" required placeholder="/articoli/nuovo-titolo/"></label><label>Tipo<select name="code"><option value="301">301 · Permanente</option><option value="302">302 · Temporaneo</option></select></label><button class="primary" style="justify-self:start">Aggiungi reindirizzamento</button></form></div>`;if(settingTab==='data')body=`<h2>Dati e backup</h2><p>Conserva una copia del tuo lavoro e controlla il collegamento.</p><div class="panel"><div class="section-heading"><div><h2>Esporta la redazione</h2><p>Contenuti, metadati, categorie, numeri e impostazioni in formato JSON.</p></div></div><p class="muted small">I file caricati rimangono nella libreria media e non sono inclusi nel JSON. ${mode==='local'?'Scarica anche le immagini originali prima di cancellare i dati del browser.':''}</p><button data-action="export" style="margin-top:15px">${icon('download')}Esporta contenuti</button><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><div class="section-heading"><div><h2>Importa un backup</h2><p>L’importazione aggiunge i contenuti senza sovrascrivere quelli esistenti.</p></div></div><button data-action="import" ${mode==='remote'?'disabled':''}>${icon('upload')}Importa JSON</button>${mode==='remote'?'<p class="field-note">L’importazione massiva è disponibile nello spazio locale. Per il CMS usa la migrazione documentata.</p>':''}<hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><div class="section-heading"><div><h2>Collegamento CMS</h2><p>${mode==='remote'?'Redazione collegata con sessione protetta.':'Le modifiche attuali sono isolate su questo dispositivo.'}</p></div></div><button data-action="connect">${icon('cloud')}Gestisci collegamento</button><p class="field-note">I backup locali e i dati remoti restano separati.</p></div>`;$('#main').innerHTML=pageHeading('Impostazioni','Le fondamenta del progetto, in ordine.')+`<div class="settings-layout"><nav class="settings-nav" aria-label="Sezioni impostazioni">${tabs.map(([id,label])=>`<button data-setting-tab="${id}" aria-selected="${settingTab===id}">${label}</button>`).join('')}</nav><section class="settings-pane">${body}</section></div>`;}
async function saveSettings(patch){const next={...state.settings,...patch};if(mode==='remote'){const payload=serializeRow('settings',next);const response=await request(`/api/cms?resource=settings${next.id?`&id=${encodeURIComponent(next.id)}`:''}`,{method:next.id?'PATCH':'POST',body:JSON.stringify(payload)});state.settings=response.data;}else state.settings=next;activity('Impostazioni del progetto aggiornate.');persist();toast(mode==='local'?'Impostazioni salvate su questo dispositivo.':'Impostazioni aggiornate.');}
function markdownPreview(text){return text.split(/\n{2,}/).map(block=>{if(block==='---')return '<hr>';if(block.startsWith('## '))return `<h2>${esc(block.slice(3))}</h2>`;if(block.startsWith('> '))return `<blockquote>${esc(block.slice(2))}</blockquote>`;const match=block.match(/^!\[([^\]]*)\]\(([^)]+)\)$/);if(match){const url=safeUrl(match[2]);return url?`<figure><img src="${esc(url)}" alt="${esc(match[1])}"></figure>`:'';}if(block.startsWith('- '))return `<ul>${block.split('\n').map(line=>`<li>${esc(line.replace(/^- /,''))}</li>`).join('')}</ul>`;return `<p>${esc(block)}</p>`;}).join('');}
function previewEntry(id){const e=editorId===id&&$('#editor-form')?collectEditor():state.entries.find(x=>x.id===id);if(!e)return;showModal('Anteprima del contenuto',`<article class="preview-article"><p class="preview-label">Anteprima redazionale · ${mode==='local'?'Bozza su questo dispositivo':esc(statuses[e.status])}</p><h1>${esc(e.title)}</h1><p class="muted">${esc(e.excerpt)}</p>${cover(e)?`<img src="${esc(cover(e))}" alt="${esc(e.metadata?.image_alt||'')}">`:''}${markdownPreview(e.body)}</article>`,true);}
async function showRevisions(id){try{if(mode==='remote')state.revisions=await resource('revisions');const items=state.revisions.filter(r=>r.entry_id===id);showModal('Revisioni del contenuto',items.length?items.map(r=>`<div class="revision-row"><div>${esc(r.snapshot?.title||'Versione precedente')}<small>${stamp(r.created_at)}</small></div><button data-action="restore-revision" data-id="${esc(r.id)}">Ripristina</button></div>`).join(''):empty('La cronologia inizia dal prossimo salvataggio.','Ogni versione salvata sarà disponibile qui per confronto e ripristino.','','clock'));}catch(error){toast(errorText(error));}}
async function connectDialog(){if(mode==='remote'){showModal('Il tuo accesso',`<div class="login-layout"><h3>${esc(account?.profile?.display_name||'Redazione Lavanda')}</h3><p>${esc(account?.user?.email||'')}<br>${esc(roles[account?.profile?.role]||'Utente')}</p><div class="notice"><strong>CMS collegato</strong><br>Le modifiche vengono salvate nel database. Gli accessi e la pubblicazione seguono i permessi del tuo ruolo.</div><div class="dialog-actions"><button data-action="logout">Esci dalla redazione</button></div></div>`);return;}showModal('Accedi a Lavanda Studio',config.configured?`<form id="login-form" class="login-layout"><h3>Rientra nella ricerca.</h3><p>Accedi con il tuo account redazionale. Lo spazio locale resta separato e non viene caricato automaticamente.</p><div class="field-stack"><label>Email<input type="email" name="email" autocomplete="username" required></label><label>Password<input type="password" name="password" autocomplete="current-password" required minlength="8"></label></div><div id="login-error" role="alert"></div><button class="primary wide" style="margin-top:22px">${icon('lock')}Accedi al CMS</button></form>`:`<div class="login-layout"><h3>Lo spazio è pronto.</h3><p>Il collegamento al CMS richiede database, archiviazione media e account amministratore. Nel frattempo puoi scrivere, organizzare e provare tutte le operazioni locali.</p><div class="notice"><strong>Configurazione da completare</strong><br>I parametri di collegamento si impostano nel progetto Vercel. Le istruzioni tecniche sono nel repository. Nessuna chiave privata va inserita in questa interfaccia.</div><div class="dialog-actions"><button data-action="close-modal">Continua nello spazio locale</button></div></div>`);}
function updateMode(){const remote=mode==='remote';$('#connection-label').textContent=remote?'CMS collegato':'Spazio locale';$('.connection').classList.toggle('connected',remote);$('#account-name').textContent=remote?account?.profile?.display_name||account?.user?.email||'Redazione':'Spazio locale';$('#account-role').textContent=remote?roles[account?.profile?.role]||'Utente':'Su questo dispositivo';$('.sidebar-foot .avatar').textContent=remote?(account?.profile?.display_name||'R')[0].toUpperCase():'M';$('#mode-banner').hidden=remote;$('#nav-content-count').textContent=state.entries.filter(e=>e.status!=='trash').length;$$('[data-action="new-entry"],[data-action="new-issue"],[data-action="upload"]').forEach(b=>b.disabled=!can('write'));if(mode==='remote'&&!can('manage')&&currentRoute==='settings')$$('form input,form select,form textarea,form button,[data-action^=nav-],[data-action=delete-redirect]',$('#main')).forEach(b=>b.disabled=true);}
async function loadRemote(){const sets=await Promise.allSettled(['entries','media','taxonomies','settings','profiles','redirects','comments'].map(resource));const names=['entries','media','taxonomies','settings','profiles','redirects','comments'];sets.forEach((r,i)=>{if(r.status==='fulfilled'){if(names[i]==='settings')state.settings=Array.isArray(r.value)?r.value[0]||state.settings:r.value||state.settings;else state[names[i]]=r.value||[];}else if(!['profiles','comments','redirects'].includes(names[i]))throw r.reason;});state.entries=state.entries.map(normalEntry);state.activity=[];activity('Accesso alla redazione collegata.');}
async function route(){if(dirty&&currentRoute==='editor'){const saved=await saveEditor(false);if(!saved){history.replaceState(null,'',`#editor/${editorId}`);return;}}clearTimeout(autoTimer);const [name,id]=location.hash.replace('#','').split('/');currentRoute=labels[name]?name:'overview';editorId=currentRoute==='editor'?id:null;$('#breadcrumb').textContent=labels[currentRoute];$$('[data-nav]').forEach(a=>{const active=a.dataset.nav===(currentRoute==='editor'?'contents':currentRoute);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#sidebar').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');const render={overview:renderOverview,contents:renderContents,editor:renderEditor,media:renderMedia,fanzine:renderFanzine,taxonomy:renderTaxonomy,analytics:renderAnalytics,team:renderTeam,settings:renderSettings,comments:renderComments};render[currentRoute]();updateMode();window.scrollTo({top:0,behavior:'instant'});}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportData(){const copy={format:'lavanda-studio',version:1,exported_at:new Date().toISOString(),...state};download(`lavanda-redazione-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(copy,null,2));toast('Backup dei contenuti esportato. I file media sono esclusi.');}
async function newEntry(type='post'){if(!can('write'))return toast('Il tuo ruolo consente solo la lettura.');const row={type,title:'Senza titolo',slug:`nuovo-${Date.now()}`,body:'',excerpt:'',status:'draft',tags:[],seo:{},metadata:{}};if(type==='fanzine'){row.title='Nuovo numero';row.metadata={issue_number:String(state.entries.filter(e=>e.type==='fanzine').length).padStart(2,'0'),article_ids:[]};}try{const saved=await saveRow('entries',row);activity(`${types[type]} creato.`);persist();if(type==='fanzine'){renderFanzine();showIssue(saved.id);}else location.hash=`editor/${saved.id}`;}catch(error){toast(errorText(error));}}
async function confirmAction(title,message,callback,button='Conferma'){showModal(title,`<p class="muted" style="font-size:13px;line-height:1.8">${esc(message)}</p><div class="dialog-actions"><button data-action="close-modal">Annulla</button><button class="danger" id="confirm-action">${esc(button)}</button></div>`);$('#confirm-action').addEventListener('click',async()=>{try{await callback();closeModal();}catch(error){toast(errorText(error));}},{once:true});}
async function editIssueOrder(action,id,issueId){const original=state.entries.find(x=>x.id===issueId);const e=captureIssueForm({...original});const ids=[...(e.metadata?.article_ids||[])];const i=ids.indexOf(id);if(action==='issue-add'){const selected=$('#issue-add-select')?.value;if(selected&&!ids.includes(selected))ids.push(selected);}else if(action==='issue-remove')ids.splice(i,1);else{const to=action==='issue-up'?i-1:i+1;if(to>=0&&to<ids.length)[ids[i],ids[to]]=[ids[to],ids[i]];}e.metadata={...e.metadata,article_ids:ids};await saveRow('entries',e);persist();showIssue(issueId);}
function showProfile(id){const p=state.profiles.find(p=>p.id===id);showModal('Accesso redazionale',`<form id="profile-form" data-id="${esc(p.id)}" class="field-stack"><label>Nome<input name="display_name" required value="${esc(p.display_name)}"></label><label>Ruolo<select name="role">${Object.entries(roles).map(([id,label])=>`<option value="${id}" ${id===p.role?'selected':''}>${label}</option>`).join('')}</select></label><label class="check-field"><input name="active" type="checkbox" ${p.active?'checked':''}>Accesso attivo</label><div class="notice">I cambiamenti di ruolo vengono applicati dal server. Mantieni almeno un account amministratore attivo.</div><div class="dialog-actions"><button type="button" data-action="close-modal">Annulla</button><button class="primary">Salva accesso</button></div></form>`);}

function renderComments(){const statusLabels={pending:'Da approvare',approved:'Approvato',spam:'Spam',trash:'Cestino'};$('#main').innerHTML=pageHeading('Conversazioni','Leggi e modera i contributi arrivati alla redazione.')+`<section class="panel no-pad">${state.comments.length?`<div class="table-wrap"><table><thead><tr><th>Contributo</th><th>Contenuto</th><th>Stato</th><th>Azioni</th></tr></thead><tbody>${state.comments.map(c=>`<tr><td><strong style="font-weight:500">${esc(c.author_name)}</strong><p class="muted small" style="max-width:420px;white-space:pre-line">${esc(c.body)}</p><small class="muted">${stamp(c.created_at)}</small></td><td class="small">${esc(state.entries.find(e=>e.id===c.entry_id)?.title||'Contenuto non disponibile')}</td><td><span class="pill">${esc(statusLabels[c.status])}</span></td><td><div class="table-actions"><button data-action="comment-approve" data-id="${esc(c.id)}" aria-label="Approva contributo di ${esc(c.author_name)}">${icon('check')}</button><button data-action="comment-spam" data-id="${esc(c.id)}" aria-label="Segna come spam">${icon('lock')}</button><button data-action="comment-trash" data-id="${esc(c.id)}" aria-label="Sposta nel cestino">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('Uno spazio per il dialogo.','I commenti ricevuti compariranno qui. Il modulo pubblico di raccolta va attivato nella configurazione del progetto.','','comment')}</section><p class="muted small" style="margin-top:18px">${mode==='local'?'Nessun commento simulato nello spazio locale.':'La moderazione è riservata ad amministratrice ed editor.'}</p>`;}
function captureIssueForm(entry){const form=$('#issue-form');if(!form)return entry;const fd=new FormData(form);return {...entry,title:fd.get('title'),metadata:{...entry.metadata,issue_number:fd.get('issue_number'),subtitle:fd.get('subtitle')},fanzine_pages:(entry.fanzine_pages||[]).map((page,index)=>({...page,title:fd.get(`page_title_${index}`)||'',body:fd.get(`page_body_${index}`)||'',layout:fd.get(`page_layout_${index}`)||'text',media_id:fd.get(`page_media_${index}`)||null}))};}
function issuePageFields(e){const layouts={text:'Testo',photo:'Fotografia',cover:'Copertina',quote:'Citazione'};return `<div class="section-heading" style="margin-top:30px"><div><h2>Pagine della fanzine</h2><p>Un percorso visivo, indipendente dalla raccolta articoli.</p></div><button type="button" data-action="issue-page-add" data-id="${esc(e.id)}" class="text-button">${icon('plus')}Aggiungi pagina</button></div><div class="issue-pages">${(e.fanzine_pages||[]).map((p,i)=>`<details class="issue-page" ${i===(e.fanzine_pages||[]).length-1?'open':''}><summary>Pagina ${i+1}${p.title?` · ${esc(p.title)}`:''}</summary><div class="field-stack"><div class="field-grid"><label>Titolo<input name="page_title_${i}" value="${esc(p.title)}" maxlength="240"></label><label>Layout<select name="page_layout_${i}">${Object.entries(layouts).map(([v,l])=>`<option value="${v}" ${p.layout===v?'selected':''}>${l}</option>`).join('')}</select></label></div><label>Testo<textarea name="page_body_${i}" rows="5" maxlength="10000">${esc(p.body)}</textarea></label><label>Immagine<select name="page_media_${i}"><option value="">Nessuna immagine</option>${state.media.filter(m=>m.mime_type?.startsWith('image/')).map(m=>`<option value="${esc(m.id)}" ${p.media_id===m.id?'selected':''}>${esc(m.title)}</option>`).join('')}</select></label><div style="display:flex;gap:6px;justify-content:flex-end"><button type="button" data-action="issue-page-up" data-id="${esc(e.id)}" data-index="${i}" ${i===0?'disabled':''} aria-label="Sposta pagina su">${icon('up')}</button><button type="button" data-action="issue-page-remove" data-id="${esc(e.id)}" data-index="${i}" class="danger">Rimuovi pagina</button></div></div></details>`).join('')||'<p class="muted small">Aggiungi una prima pagina per comporre una fanzine con testo e immagini.</p>'}</div>`;}

document.addEventListener('click',async event=>{const tab=event.target.closest('[data-status]');if(tab){filters.status=tab.dataset.status;renderContents();return;}const setting=event.target.closest('[data-setting-tab]');if(setting){settingTab=setting.dataset.settingTab;renderSettings();return;}const block=event.target.closest('[data-block]');if(block){const area=$('#entry-body');if(block.dataset.block==='image'){showModal('Inserisci un’immagine',`<p class="muted small">Copia l’indirizzo di un’immagine dalla libreria e aggiungi un testo alternativo.</p><form id="insert-image-form" class="field-stack"><label>Indirizzo immagine<input name="url" type="url" required placeholder="https://…"></label><label>Testo alternativo<input name="alt" placeholder="Descrizione dell’immagine"></label><div class="dialog-actions"><button class="primary">Inserisci nel testo</button></div></form>`);return;}const blocks={heading:'\n\n## Titolo della sezione\n\n',paragraph:'\n\nNuovo paragrafo\n\n',quote:'\n\n> Una citazione, con la sua fonte.\n\n',list:'\n\n- Primo punto\n- Secondo punto\n\n',separator:'\n\n---\n\n'};area.setRangeText(blocks[block.dataset.block],area.selectionStart,area.selectionEnd,'end');area.focus();area.dispatchEvent(new Event('input',{bubbles:true}));return;}const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;try{if(action==='menu'){const open=$('#sidebar').classList.toggle('open');b.setAttribute('aria-expanded',String(open));}else if(action==='theme'){document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';localStorage.setItem('lavanda-studio-theme',document.documentElement.dataset.theme);}else if(action==='new-entry')await newEntry();else if(action==='new-issue')await newEntry('fanzine');else if(action==='edit-entry')location.hash=`editor/${id}`;else if(action==='save-editor')await saveEditor();else if(action==='view-site')window.open('/','_blank','noopener');else if(action==='preview')previewEntry(id);else if(action==='revisions')await showRevisions(id);else if(action==='close-modal')closeModal();else if(action==='connect')await connectDialog();else if(action==='export')exportData();else if(action==='import')$('#import-input').click();else if(action==='upload')$('#file-input').click();else if(action==='media-detail')showMedia(id);else if(action==='pick-cover'){if(!await saveEditor(false))return;openMediaPicker(id);}else if(action==='remove-cover'){if(!await saveEditor(false))return;const e=state.entries.find(e=>e.id===id);await saveRow('entries',{...e,cover_media_id:null,metadata:{...e.metadata,cover_url:''}});persist();renderEditor();}else if(action==='select-media'){const e=state.entries.find(e=>e.id===mediaPicker);const m=state.media.find(m=>m.id===id);await saveRow('entries',{...e,cover_media_id:id,metadata:{...e.metadata,cover_url:m.local_file?'':m.public_url,image_alt:m.alt}});persist();closeModal();renderEditor();toast('Immagine di copertina aggiornata.');}else if(action==='duplicate-entry'){const e=state.entries.find(e=>e.id===id);const copy={...e,title:`${e.title} · copia`,slug:`${e.slug}-copia-${Date.now()}`,status:'draft'};delete copy.id;delete copy.version;const saved=await saveRow('entries',copy);persist();toast('Copia creata in bozza.');location.hash=`editor/${saved.id}`;}else if(action==='trash-entry'){const e=state.entries.find(e=>e.id===id);if(e.status==='trash'&&mode==='remote'){await saveRow('entries',{...e,status:'draft'});persist();renderContents();toast('Contenuto ripristinato come bozza.');}else if(e.status==='trash'){confirmAction('Elimina definitivamente',`Il contenuto «${e.title}» sarà eliminato da questo spazio.`,async()=>{await removeRow('entries',id);renderContents();},'Elimina');}else{await saveRow('entries',{...e,status:'trash'});persist();renderContents();toast('Contenuto spostato nel cestino.');}}else if(action==='delete-media'){const linked=state.entries.filter(e=>e.cover_media_id===id||e.fanzine_pages?.some(p=>p.media_id===id));if(linked.length)return toast(`Il media è usato in ${linked.length} contenuti. Rimuovi prima i collegamenti.`);confirmAction('Elimina media','Il file e i suoi dettagli saranno rimossi da questo spazio.',async()=>{const m=state.media.find(m=>m.id===id);await removeRow('media',id);if(m.local_file)await blobStore('delete',id);if(mediaUrls.has(id)){URL.revokeObjectURL(mediaUrls.get(id));mediaUrls.delete(id);}activity('Media eliminato.');persist();renderMedia();toast('Media eliminato.');},'Elimina');}else if(action==='edit-issue')showIssue(id);else if(action.startsWith('issue-page-')){const e=state.entries.find(e=>e.id===id);const next=captureIssueForm(e);const pages=[...(next.fanzine_pages||[])];const index=Number(b.dataset.index);if(action==='issue-page-add')pages.push({title:'',body:'',layout:'text',media_id:null});else if(action==='issue-page-remove')pages.splice(index,1);else if(index>0)[pages[index-1],pages[index]]=[pages[index],pages[index-1]];await saveRow('entries',{...next,fanzine_pages:pages});persist();showIssue(id);}else if(action.startsWith('comment-')){if(mode==='remote'&&!can('publish'))return toast('La moderazione richiede un editor.');const c=state.comments.find(c=>c.id===id);const status={"comment-approve":"approved","comment-spam":"spam","comment-trash":"trash"}[action];await saveRow('comments',{...c,status});persist();renderComments();toast('Stato del contributo aggiornato.');}else if(action.startsWith('issue-'))await editIssueOrder(action,id,b.dataset.issue);else if(action==='edit-taxonomy'){const t=state.taxonomies.find(x=>x.id===id);showModal('Modifica '+(t.kind==='category'?'categoria':'tag'),`<form id="taxonomy-form" data-id="${esc(id)}" class="field-stack"><label>Nome<input name="name" value="${esc(t.name)}" required></label><label>Indirizzo<input name="slug" value="${esc(t.slug)}" required></label><label>Descrizione<textarea name="description">${esc(t.description)}</textarea></label><div class="dialog-actions"><button class="primary">Salva</button></div></form>`);}else if(action==='delete-taxonomy'){const t=state.taxonomies.find(t=>t.id===id);const used=t.kind==='category'?state.entries.some(e=>e.category_id===id):state.entries.some(e=>e.tags?.includes(t.name));if(used)return toast('La voce è utilizzata. Rimuovila prima dai contenuti.');confirmAction('Elimina voce',`Eliminare «${t.name}»?`,async()=>{await removeRow('taxonomies',id);renderTaxonomy();},'Elimina');}else if(action==='restore-revision'){const r=state.revisions.find(r=>r.id===id);const original=state.entries.find(e=>e.id===r.entry_id);await saveRow('entries',{...r.snapshot,id:original.id,version:original.version,status:'draft'});persist();closeModal();renderEditor();toast('Versione ripristinata come bozza.');}else if(action==='delete-redirect'){await removeRow('redirects',id);renderSettings();}else if(action==='nav-up'||action==='nav-remove'){const nav=[...(state.settings.navigation||[])];const index=Number(b.dataset.index);if(action==='nav-remove')nav.splice(index,1);else [nav[index-1],nav[index]]=[nav[index],nav[index-1]];await saveSettings({navigation:nav});renderSettings();}else if(action==='analytics-export'){const data=window.__lavandaAnalytics;if(!data)return toast('Collega le analytics per esportare dati reali.');const rows=['data,evento,conteggio',...data.daily.map(r=>`${r.date},${r.event},${r.count}`)];download(`lavanda-analytics-${filters.days}giorni.csv`,rows.join('\n'),'text/csv');}else if(action==='edit-profile')showProfile(id);else if(action==='team-add'){showModal('Aggiungi una persona',`<p class="muted" style="font-size:13px;line-height:1.8">Gli account si creano nell’area Authentication del progetto Supabase. Dopo la creazione, il profilo appare qui e puoi assegnare ruolo e accesso. Questa interfaccia non invia inviti né email.</p><div class="dialog-actions"><button data-action="close-modal">Ho capito</button></div>`);}else if(action==='logout'){await request('/api/auth',{method:'POST',body:JSON.stringify({action:'logout'})});location.reload();}}catch(error){toast(errorText(error));}});
document.addEventListener('input',event=>{if(event.target.id==='content-search'){filters.search=event.target.value;$('#contents-results').innerHTML=contentTable();}else if(event.target.id==='media-search'){filters.mediaSearch=event.target.value;$('#media-results').innerHTML=mediaGrid();}else if(event.target.closest('#editor-form')){dirty=true;$('#save-status').textContent='Modifiche non salvate';const data=collectEditor();$('#word-count').textContent=`${words(data.body)} parole`;$('#reading-time').textContent=`${Math.max(1,Math.ceil(words(data.body)/200))} minuti di lettura`;$('#slug-preview').textContent=data.slug;clearTimeout(autoTimer);if(mode==='local')autoTimer=setTimeout(()=>saveEditor(false),1800);}});
document.addEventListener('change',event=>{if(event.target.id==='type-filter'){filters.type=event.target.value;$('#contents-results').innerHTML=contentTable();}else if(event.target.id==='media-folder'){filters.mediaFolder=event.target.value;$('#media-results').innerHTML=mediaGrid();}else if(event.target.id==='media-type'){filters.mediaType=event.target.value;$('#media-results').innerHTML=mediaGrid();}else if(event.target.id==='analytics-days'){filters.days=Number(event.target.value);renderAnalytics();}else if(event.target.id==='file-input')uploadFiles([...event.target.files]);});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,fd=new FormData(form);try{if(form.id==='editor-form')await saveEditor();else if(form.id==='media-form'){const m=state.media.find(x=>x.id===form.dataset.id);await saveRow('media',{...m,...Object.fromEntries(fd),...(mode==='remote'&&can('publish')?{published:fd.has('published')}:{})});activity(`Dati media aggiornati: ${fd.get('title')}.`);persist();closeModal();renderMedia();toast('Dettagli media salvati.');}else if(form.classList.contains('taxonomy-add')){const name=fd.get('name').trim();if(state.taxonomies.some(t=>t.kind===form.dataset.kind&&t.name.toLowerCase()===name.toLowerCase()))return toast('Questa voce esiste già.');await saveRow('taxonomies',{name,slug:slug(name),kind:form.dataset.kind,description:''});persist();renderTaxonomy();toast('Voce aggiunta.');}else if(form.id==='taxonomy-form'){const t=state.taxonomies.find(x=>x.id===form.dataset.id);await saveRow('taxonomies',{...t,...Object.fromEntries(fd)});persist();closeModal();renderTaxonomy();toast('Voce aggiornata.');}else if(form.id==='issue-form'){const e=state.entries.find(x=>x.id===form.dataset.id);await saveRow('entries',captureIssueForm(e));activity(`Numero aggiornato: ${fd.get('title')}.`);persist();closeModal();renderFanzine();toast('Numero salvato.');}else if(form.id==='settings-form'){await saveSettings({site_title:fd.get('site_title'),tagline:fd.get('tagline'),site_description:fd.get('site_description'),social_links:{...state.settings.social_links,instagram:fd.get('instagram')}});}else if(form.id==='seo-settings-form'){await saveSettings({seo:{...Object.fromEntries(fd),noindex:fd.has('noindex')}});}else if(form.id==='nav-form'){const href=fd.get('href');if(!href.startsWith('/')&&!safeUrl(href))return toast('Inserisci un percorso / oppure un indirizzo https valido.');await saveSettings({navigation:[...(state.settings.navigation||[]),Object.fromEntries(fd)]});renderSettings();}else if(form.id==='redirect-form'){const target=fd.get('target');if(!target.startsWith('/')&&!safeUrl(target))return toast('Inserisci un percorso o un indirizzo valido.');await saveRow('redirects',{source:fd.get('source'),target,code:Number(fd.get('code'))});persist();renderSettings();toast('Reindirizzamento salvato.');}else if(form.id==='profile-form'){const p=state.profiles.find(p=>p.id===form.dataset.id);await saveRow('profiles',{...p,...Object.fromEntries(fd),active:fd.has('active')});closeModal();renderTeam();toast('Accesso aggiornato.');}else if(form.id==='insert-image-form'){const url=safeUrl(fd.get('url'));if(!url)return toast('Indirizzo non valido.');const area=$('#entry-body');area.setRangeText(`\n\n![${fd.get('alt').replace(/[\[\]]/g,'')}](${url})\n\n`,area.selectionStart,area.selectionEnd,'end');closeModal();area.dispatchEvent(new Event('input',{bubbles:true}));}else if(form.id==='login-form'){const localSnapshot=JSON.parse(JSON.stringify(state));const button=$('button[type=submit],button.primary',form);button.disabled=true;$('#login-error').innerHTML='';try{const response=await request('/api/auth',{method:'POST',body:JSON.stringify({action:'login',email:fd.get('email'),password:fd.get('password')})});account=response.data;mode='remote';await loadRemote();closeModal();await hydrateMedia();route();toast('Accesso alla redazione riuscito.');}catch(error){mode='local';state=localSnapshot;account=null;$('#login-error').innerHTML=`<div class="error-message">${esc(errorText(error))}</div>`;}finally{button.disabled=false;}}}catch(error){toast(errorText(error));}});
document.addEventListener('dragover',event=>{if(event.target.closest('#drop-zone')){event.preventDefault();$('#drop-zone').classList.add('dragover');}});document.addEventListener('dragleave',event=>{if(event.target.closest('#drop-zone'))$('#drop-zone').classList.remove('dragover');});document.addEventListener('drop',event=>{if(event.target.closest('#drop-zone')){event.preventDefault();$('#drop-zone').classList.remove('dragover');uploadFiles([...event.dataTransfer.files]);}});
$('#import-input').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('Backup troppo grande. Limite: 10 MB.');const data=JSON.parse(await file.text());if(data.format!=='lavanda-studio'||!Array.isArray(data.entries))throw new Error('Questo file non è un backup Lavanda Studio.');const ids=new Map();for(const e of data.entries){const id=uid();ids.set(e.id,id);state.entries.push({...normalEntry(e),id,status:'draft',cover_media_id:null,metadata:{...e.metadata,cover_url:safeUrl(e.metadata?.cover_url)||''}});}state.entries.filter(e=>[...ids.values()].includes(e.id)&&e.type==='fanzine').forEach(e=>e.metadata.article_ids=(e.metadata.article_ids||[]).map(id=>ids.get(id)).filter(Boolean));activity(`${data.entries.length} contenuti importati da backup.`);persist();renderSettings();toast('Contenuti importati come bozze. Media e account esclusi.');}catch(error){toast(errorText(error));}event.target.value='';});
$('#modal').addEventListener('close',()=>{mediaPicker=null;});
window.addEventListener('hashchange',route);window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key==='s'&&currentRoute==='editor'){event.preventDefault();saveEditor();}if(event.key==='Escape'){$('#sidebar').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');}});$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeModal();}});
async function init(){try{document.documentElement.dataset.theme=localStorage.getItem('lavanda-studio-theme')||'light';const saved=localStorage.getItem(storageKey);if(saved)state={...state,...JSON.parse(saved)};else await seed();}catch{await seed();}try{config=await request('/api/config');if(config.configured){const localSnapshot=JSON.parse(JSON.stringify(state));try{account=(await request('/api/auth')).data;mode='remote';await loadRemote();}catch(error){mode='local';state=localSnapshot;account=null;if(error.status!==401)toast(`CMS non disponibile: ${errorText(error)} Lo spazio locale è separato.`);}}}catch{config={configured:false};}await hydrateMedia();icons();await route();}
init();
